//! ESSENTIAL PROCESS:
//! gRPC server for log messages, supporting high-throughput ingestion,
//! ring-buffer querying (GetTailLogs), and real-time streaming (StreamLogs).
//!
//! DATA FLOW:
//! 1. Ingest: Incoming LogRequest -> handle_grpc_message -> writer_tx
//! 2. Query:  GetTailLogs -> LogRingBuffer.get_tail() -> TailLogsResponse
//! 3. Stream: StreamLogs -> LogRingBuffer.subscribe() -> HTTP/2 server-streaming
//!
//! KEY PARAMETERS:
//! - LogBridge: Service trait generated by tonic from log_service.proto.
//! - ring_buffer: Shared Arc<LogRingBuffer> providing in-memory logs and broadcast.

use std::pin::Pin;
use std::sync::atomic::AtomicU64;
use std::sync::Arc;
use tokio::sync::mpsc;
use tokio_stream::wrappers::BroadcastStream;
use tokio_stream::StreamExt;
use tonic::{transport::Server, Request, Response, Status};

use crate::config::config::Config;
use crate::core::protocol_handlers::handle_grpc_message;
use crate::core::ring_buffer::LogRingBuffer;
use crate::line_str;
use crate::models::log_entry::LogEntry;
use crate::models::log_packet::LogPacket;
use crate::utils::terminal_ui::print_internal_log;

// Proto generated bindings
pub mod log_service {
    tonic::include_proto!("logservice");
}

use log_service::{
    log_bridge_server::{LogBridge, LogBridgeServer},
    LogRequest as ProtoLogRequest,
    LogResponse,
    StreamLogsRequest,
    TailLogsRequest,
    TailLogsResponse,
};

/// gRPC bridge gateway for log messages
pub struct LogBridgeGateway {
    config: Config,
}

//-----------------------------------------------------------------------------------------------

impl LogBridgeGateway {
    /// Create new gRPC bridge gateway
    pub fn new(config: &Config) -> Self {
        Self {
            config: config.clone(),
        }
    }

    /// Get server name
    pub fn name(&self) -> &str {
        &self.config.name
    }

    //-----------------------------------------------------------------------------------------------

    /// Run the gRPC server
    pub async fn run(
        &self,
        writer_tx: mpsc::Sender<LogPacket>,
        sequence_counter: Arc<AtomicU64>,
        ring_buffer: Arc<LogRingBuffer>,
    ) -> Result<(), Box<dyn std::error::Error>> {
        let addr = format!(
            "{host}:{port}",
            host = self.config.host,
            port = self.config.grpc_port
        )
        .parse()?;
        let service = LogBridgeServiceImpl::new(&self.config, writer_tx, sequence_counter, ring_buffer);

        print_internal_log(
            "INFO",
            &self.config.name,
            "grpc_server.rs",
            "run",
            line_str!(),
            &format!("Log Bridge listening on {}", addr),
        );

        Server::builder()
            .add_service(LogBridgeServer::new(service))
            .serve(addr)
            .await?;

        Ok(())
    }
}

//-----------------------------------------------------------------------------------------------

/// gRPC bridge service implementation
pub struct LogBridgeServiceImpl {
    server_name: String,
    writer_tx: mpsc::Sender<LogPacket>,
    sequence_counter: Arc<AtomicU64>,
    ring_buffer: Arc<LogRingBuffer>,
}

//-----------------------------------------------------------------------------------------------

impl LogBridgeServiceImpl {
    /// Create new gRPC bridge implementation
    pub fn new(
        config: &Config,
        writer_tx: mpsc::Sender<LogPacket>,
        sequence_counter: Arc<AtomicU64>,
        ring_buffer: Arc<LogRingBuffer>,
    ) -> Self {
        Self {
            server_name: config.name.clone(),
            writer_tx,
            sequence_counter,
            ring_buffer,
        }
    }
}

//-----------------------------------------------------------------------------------------------

#[tonic::async_trait]
impl LogBridge for LogBridgeServiceImpl {
    type StreamLogsStream = Pin<
        Box<dyn tokio_stream::Stream<Item = Result<ProtoLogRequest, Status>> + Send + 'static>,
    >;

    /// Handle incoming gRPC log message
    async fn log_message(
        &self,
        request: Request<ProtoLogRequest>,
    ) -> Result<Response<LogResponse>, Status> {
        let remote_addr = request.remote_addr();
        let client_id = match remote_addr {
            Some(addr) => format!("grpc_client_{}", addr),
            None => "grpc_client_unknown".to_string(),
        };
        let log_data = request.into_inner();

        let internal_request = LogEntry::from(log_data);
        match handle_grpc_message(
            internal_request,
            self.writer_tx.clone(),
            self.sequence_counter.clone(),
        )
        .await
        {
            Ok(_) => Ok(Response::new(LogResponse { success: true })),
            Err(e) => {
                print_internal_log(
                    "ERROR",
                    &self.server_name,
                    "grpc_server.rs",
                    "log_message",
                    line_str!(),
                    &format!("[client: {client_id}] failed to process gRPC message: {e}"),
                );
                Err(Status::internal(format!(
                    "Failed to process log message: {e}"
                )))
            }
        }
    }

    //-----------------------------------------------------------------------------------------------

    /// Retrieve recent buffered log entries
    async fn get_tail_logs(
        &self,
        request: Request<TailLogsRequest>,
    ) -> Result<Response<TailLogsResponse>, Status> {
        let req = request.into_inner();
        let limit = if req.limit == 0 { 100 } else { req.limit as usize };
        let svc_filter = if req.service_name.is_empty() {
            None
        } else {
            Some(req.service_name.as_str())
        };
        let min_lvl = parse_level(&req.min_level);

        let entries = self.ring_buffer.get_tail(limit, svc_filter, min_lvl);
        let total_ingested = self.ring_buffer.total_ingested();
        let count = entries.len() as u32;
        let logs = entries.into_iter().map(ProtoLogRequest::from).collect();

        Ok(Response::new(TailLogsResponse {
            logs,
            count,
            total_ingested,
        }))
    }

    //-----------------------------------------------------------------------------------------------

    /// Stream incoming log entries in real-time over HTTP/2
    async fn stream_logs(
        &self,
        request: Request<StreamLogsRequest>,
    ) -> Result<Response<Self::StreamLogsStream>, Status> {
        let req = request.into_inner();
        let service_filter = req.service_name;
        let min_level_num = parse_level(&req.min_level);

        let rx = self.ring_buffer.subscribe();
        let broadcast_stream = BroadcastStream::new(rx);

        let output_stream = broadcast_stream.filter_map(move |item| match item {
            Ok(entry) => {
                if !service_filter.is_empty() && entry.service_name != service_filter {
                    return None;
                }
                if let Some(min_lvl) = min_level_num {
                    if entry.level < min_lvl {
                        return None;
                    }
                }
                Some(Ok(ProtoLogRequest::from(entry)))
            }
            Err(_) => {
                // Lagged or disconnected receiver skipped gracefully
                None
            }
        });

        Ok(Response::new(
            Box::pin(output_stream) as Self::StreamLogsStream
        ))
    }
}

//-----------------------------------------------------------------------------------------------

/// Parse string log level or integer into numeric level
fn parse_level(lvl: &str) -> Option<i32> {
    let trimmed = lvl.trim();
    if trimmed.is_empty() {
        return None;
    }
    if let Ok(num) = trimmed.parse::<i32>() {
        return Some(num);
    }
    match trimmed.to_uppercase().as_str() {
        "NOTSET" => Some(0),
        "DEBUG" => Some(1),
        "STREAM" => Some(2),
        "INFO" => Some(3),
        "LOGON" => Some(4),
        "LOGOUT" => Some(5),
        "TRADE" => Some(6),
        "SCHEDULE" => Some(7),
        "REPORT" => Some(8),
        "WARNING" => Some(9),
        "ERROR" => Some(10),
        "CRITICAL" => Some(11),
        _ => None,
    }
}

//-----------------------------------------------------------------------------------------------

// Conversion from protobuf to internal type
impl From<ProtoLogRequest> for LogEntry {
    fn from(request: ProtoLogRequest) -> Self {
        Self {
            timestamp: request.timestamp,
            hostname: request.hostname,
            logger_name: request.logger_name,
            level: request.level,
            module: request.module,
            filename: request.filename,
            function_name: request.function_name,
            line_number: request.line_number,
            message: request.message,
            path_name: request.path_name,
            process_id: request.process_id,
            process_name: request.process_name,
            thread_id: request.thread_id,
            thread_name: request.thread_name,
            service_name: request.service_name,
            stack_trace: request.stack_trace,
        }
    }
}

//-----------------------------------------------------------------------------------------------

// Conversion from internal type to protobuf
impl From<LogEntry> for ProtoLogRequest {
    fn from(entry: LogEntry) -> Self {
        Self {
            timestamp: entry.timestamp,
            hostname: entry.hostname,
            logger_name: entry.logger_name,
            level: entry.level,
            module: entry.module,
            filename: entry.filename,
            function_name: entry.function_name,
            line_number: entry.line_number,
            message: entry.message,
            path_name: entry.path_name,
            process_id: entry.process_id,
            process_name: entry.process_name,
            thread_id: entry.thread_id,
            thread_name: entry.thread_name,
            service_name: entry.service_name,
            stack_trace: entry.stack_trace,
        }
    }
}
